import socket, threading, struct, time, subprocess

def parse_q(data):
    off=12
    while True:
        l=data[off]
        if l==0:
            off+=1
            break
        off+=1+l
    off+=4
    return off

def encode_name(name):
    name=name.rstrip('.')
    if name=="": return b'\x00'
    b=b''
    for part in name.split('.'):
        b+=bytes([len(part)])+part.encode()
    return b+b'\x00'

def encode_txt(s):
    b=s.encode()
    return bytes([len(b)])+b

def server(port, stop, handler):
    s=socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.bind(('127.0.0.1', port))
    s.settimeout(0.5)
    while not stop[0]:
        try:
            data,addr=s.recvfrom(4096)
        except: continue
        try:
            txid,flags,qd,an,ns,ar=struct.unpack('!HHHHHH', data[:12])
            q_end=parse_q(data)
            question=data[12:q_end]
            off=q_end-4
            qtype,qclass=struct.unpack('!HH', data[off:off+4])
            resp_code, answers, auths, adds = handler(qtype)
            flags_resp=0x8180|(resp_code&0xF)
            hdr=struct.pack('!HHHHHH', txid, flags_resp, 1, len(answers), len(auths), len(adds))
            resp=hdr+question+b''.join(answers)+b''.join(auths)+b''.join(adds)
            s.sendto(resp, addr)
        except Exception as e:
            print("server err",e)
    s.close()

def rr(rtype, ttl, rdata, rclass=1):
    return struct.pack('!HHHIH', 0xc00c, rtype, rclass, ttl, len(rdata))+rdata

stop=[False]
port=15357

def handler(qtype):
    if qtype==13:
        rdata=encode_txt("CPU")+encode_txt("Linux")
        return (0, [rr(13,300,rdata)], [], [])
    elif qtype==29:
        rdata2=struct.pack('!BBBB',0,0x12,0x16,0x13)+struct.pack('!III', 0x80000000, 0x80000000, 100*100+10000000)
        return (0, [rr(29,300,rdata2)], [], [])
    elif qtype==35:
        rdata=struct.pack('!HH',100,10)+encode_txt("S")+encode_txt("SIP+D2U")+encode_txt("!^.*$!sip:info@bar.example.com!")+encode_name(".")
        return (0, [rr(35,300,rdata)], [], [])
    elif qtype==52:
        rdata=struct.pack('!BBB',3,1,1)+bytes.fromhex('d2abde240d7cd3ee6b4d704e967c48d4ca1e0c2d707b6c89954b28eaa7c50fa00')
        return (0, [rr(52,300,rdata)], [], [])
    elif qtype==44:
        rdata=struct.pack('!BB',2,1)+bytes.fromhex('123456789abcdef123456789abcdef123456789a12')
        return (0, [rr(44,300,rdata)], [], [])
    elif qtype==18:
        rdata=struct.pack('!H',1)+encode_name('afs.example.net.')
        return (0, [rr(18,300,rdata)], [], [])
    elif qtype==255:
        return (0, [rr(1,300,socket.inet_aton('5.6.7.8'))], [], [])
    elif qtype==99:
        return (0, [rr(99,300,b'\x01\x02\x03\x04')], [], [])
    else:
        return (0, [rr(qtype,300,b'\xde\xad\xbe\xef')], [], [])

import threading
t=threading.Thread(target=server,args=(port,stop,handler),daemon=True)
t.start()
time.sleep(0.3)

def run(typ):
    p=subprocess.run(['./executable','example.net',typ,f'@127.0.0.1:{port}'], capture_output=True, timeout=5)
    print(f"TYPE {typ} RC={p.returncode} OUT={p.stdout!r} ERR={p.stderr!r}", flush=True)
    pj=subprocess.run(['./executable','example.net',typ,f'@127.0.0.1:{port}','-J'], capture_output=True, timeout=5)
    print(f"  JSON={pj.stdout!r} JSONERR={pj.stderr!r}", flush=True)

for typ in ["HINFO","LOC","NAPTR","TLSA","SSHFP","AFSDB","ANY"]:
    run(typ)
run("99")
stop[0]=True
t.join()
print("done")
PY"}

