def build_rdata(tname):
    if tname=="A":
        return struct.pack('!HHHIH', 0xc00c, 1, 1, 300, 4)+socket.inet_aton('1.1.1.1')
    elif tname=="AAAA":
        return struct.pack('!HHHIH', 0xc00c, 28, 1, 300, 16)+socket.inet_pton(socket.AF_INET6, '::1')
    elif tname=="MX":
        mx=struct.pack('!H',10)+enc('mail.example.net.')
        return struct.pack('!HHHIH', 0xc00c, 15, 1, 300, len(mx))+mx
    elif tname=="TXT":
        t=txt("hello")
        return struct.pack('!HHHIH', 0xc00c, 16, 1, 300, len(t))+t
    elif tname=="NS":
        r=enc('ns.example.net.')
        return struct.pack('!HHHIH', 0xc00c, 2, 1, 300, len(r))+r
    elif tname=="CNAME":
        r=enc('alias.example.net.')
        return struct.pack('!HHHIH', 0xc00c, 5, 1, 300, len(r))+r
    elif tname=="PTR":
        r=enc('host.example.net.')
        return struct.pack('!HHHIH', 0xc00c, 12, 1, 300, len(r))+r
    elif tname=="SOA":
        r=enc('ns.example.net.')+enc('host.example.net.')+struct.pack('!IIIII',1,7200,3600,1209600,300)
        return struct.pack('!HHHIH', 0xc00c, 6, 1, 300, len(r))+r
    elif tname=="SRV":
        r=struct.pack('!HHH',10,20,80)+enc('web.example.net.')
        return struct.pack('!HHHIH', 0xc00c, 33, 1, 300, len(r))+r
    elif tname=="CAA":
        r=struct.pack('!BB',0,5)+b'issue'+b'letsencrypt.org'
        return struct.pack('!HHHIH', 0xc00c, 257, 1, 300, len(r))+r
    elif tname=="HINFO":
        r=txt("CPU")+txt("Linux")
        return struct.pack('!HHHIH', 0xc00c, 13, 1, 300, len(r))+r
    elif tname=="LOC":
        r=struct.pack('!BBBB',0,0x12,0x16,0x13)+struct.pack('!III', 0x80000000, 0x80000000, 100*100+10000000)
        return struct.pack('!HHHIH', 0xc00c, 29, 1, 300, len(r))+r
    elif tname=="NAPTR":
        r=struct.pack('!HH',100,10)+txt("S")+txt("SIP")+txt("!^.*$!sip:!")+enc(".")
        return struct.pack('!HHHIH', 0xc00c, 35, 1, 300, len(r))+r
    elif tname=="SSHFP":
        r=struct.pack('!BB',2,1)+bytes.fromhex('bb'*20)
        return struct.pack('!HHHIH', 0xc00c, 44, 1, 300, len(r))+r
    elif tname=="TLSA":
        r=struct.pack('!BBB',3,1,1)+bytes.fromhex('aa'*32)
        return struct.pack('!HHHIH', 0xc00c, 52, 1, 300, len(r))+r
    elif tname=="URI":
        r=struct.pack('!HH',10,20)+b'https://example.net/'
        return struct.pack('!HHHIH', 0xc00c, 256, 1, 300, len(r))+r
    elif tname in ("AFSDB","ANY","AXFR","IXFR","TA","DLV","APL","CERT","KX","DNAME","DS","IPSECKEY","RRSIG","NSEC","DHCID","NSEC3","NSEC3PARAM","SMIMEA","HIP","CDS","CDNSKEY","OPENPGPKEY","CSYNC","EUI48","EUI64","TKEY","TSIG","RP","SIG","KEY"):
        # for uninterpreted, return generic 4 bytes? But they will display as byte array
        num=type_map[tname]
        # for known-but-uninterpreted, rdata can be anything
        r=b'\x01\x02\x03\x04'
        return struct.pack('!HHHIH', 0xc00c, num, 1, 300, len(r))+r
    else:
        return None

def server(port, stop):
    s=socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.bind(('127.0.0.1', port))
    s.settimeout(0.5)
    while not stop[0]:
        try:
            data,addr=s.recvfrom(4096)
        except: continue
        txid,_,_,_,_,_=struct.unpack('!HHHHHH', data[:12])
        q_end=parse_q(data)
        q=data[12:q_end]
        o=q_end-4
        qtype,_=struct.unpack('!HH', data[o:o+4])
        # find tname for qtype
        tname=None
        for k,v in type_map.items():
            if v==qtype:
                tname=k
                break
        rr=build_rdata(tname) if tname else None
        if rr is None:
            hdr=struct.pack('!HHHHHH', txid, 0x8180, 1, 0, 0, 0)
            s.sendto(hdr+q, addr)
        else:
            hdr=struct.pack('!HHHHHH', txid, 0x8180, 1, 1, 0, 0)
            s.sendto(hdr+q+rr, addr)
    s.close()

